rowdata.pyStepsJavaSource:
StringBuffer label = new StringBuffer(64);

ClassDefinition cd = tools.getDatabase().getClassDef(myStepPage.getClassName());
java.util.List Keys =  cd.getKeyPropertyList();
java.util.Iterator it = Keys.iterator();
while (it.hasNext()) {
  String key = (String) it.next();
  if (label.length() > 0) label.append("-");
  label.append(myStepPage.getString(key));
  if (label.length() > 64)   label.setLength(64);
}

myStepPage.putString("pyLabel", label.toString());

ClipboardPage pgPrimaryPage = tools.getPrimaryPage();
ClipboardProperty cpWarnings = pgPrimaryPage.getIfPresent(".pxWarnings");
ClipboardProperty cpNewWarnings = pgPrimaryPage.getIfPresent(".pxWarningsToDisplay");
// If no warnings at all, there is no need to index
if ((cpWarnings == null || cpWarnings.size() == 0)&& (cpNewWarnings == null || cpNewWarnings.size() == 0))
{
	return true;
} else if (cpWarnings != null && cpNewWarnings != null)
{
	// If there are different numbers of warnings, we definitely need to copy to pxWarnings
	if (cpWarnings.size() != cpNewWarnings.size())
	{
		bWarningsDifferent = true;
		return true;
	} else // same number of warnings
	{
		java.util.Iterator itr1 = cpWarnings.iterator();
		java.util.Iterator itr2 = cpNewWarnings.iterator();
		while (itr1.hasNext())
		{
			ClipboardProperty cpOneWarning  = (ClipboardProperty)itr1.next();
			ClipboardProperty cpOneWarningNew  = (ClipboardProperty)itr2.next();
			boolean bAllWarningsSame = true;

			// Go through all the warning data to check whether everything matches
			if (!cpOneWarning.getPageValue().getString(".pxWarningMessage").equals(cpOneWarningNew.getPageValue().getString(".pxWarningMessage")))
			{
				bAllWarningsSame = false; 
			} else if (!cpOneWarning.getPageValue().getString(".pxWarningCreateOperator").equals(cpOneWarningNew.getPageValue().getString(".pxWarningCreateOperator")))
			{
				bAllWarningsSame = false; 
			}  else if (bAllWarningsSame && !cpOneWarning.getPageValue().getString(".pxWarningName").equals(cpOneWarningNew.getPageValue().getString(".pxWarningName")))
			{
				bAllWarningsSame = false;
			} else if (bAllWarningsSame && !cpOneWarning.getPageValue().getString(".pxWarningType").equals(cpOneWarningNew.getPageValue().getString(".pxWarningType")))
			{
				bAllWarningsSame = false;

			} else if (bAllWarningsSame && !cpOneWarning.getPageValue().getString(".pxWarningSeverity").equals(cpOneWarningNew.getPageValue().getString(".pxWarningSeverity")))
			{
				bAllWarningsSame = false;
			} else if (bAllWarningsSame && !cpOneWarning.getPageValue().getString(".pxWarningDetails").equals(cpOneWarningNew.getPageValue().getString(".pxWarningDetails")))
			{
				bAllWarningsSame = false;
			}
			// If a warning didn't match, reindex
			if (bAllWarningsSame == false)
			{
				bWarningsDifferent = true;
				return true;
			}
		}
		bWarningsDifferent = false;
	} 	

} else // One of the warnings property is null and the other isn't, so we want to reindex
{
	bWarningsDifferent = true;
}
